type agreementCommentCodeHTMLField struct {
	OriginalSpan, ProjectedSpan graph.Span
	Target                      string
}

type agreementCommentCodeHTMLWindow struct {
	Text      string
	Positions []int
}

// Decoded text retains its original HTML byte locations. Entity spellings have
// no single byte owner and therefore cannot supply a renamed physical target.
func agreementCommentCodeHTMLText(raw string, offset int) agreementCommentCodeHTMLWindow {
	var result agreementCommentCodeHTMLWindow
	for at := 0; at < len(raw); {
		if raw[at] == '&' {
			if end := strings.IndexByte(raw[at:], ';'); end >= 0 {
				word := raw[at : at+end+1]
				decoded := stdhtml.UnescapeString(word)
				if decoded != word {
					result.Text += decoded
					for range len(decoded) {
						result.Positions = append(result.Positions, -1)
					}
					at += len(word)
					continue
				}
			}
		}
		if raw[at] == '\r' {
			result.Text += "\n"
			result.Positions = append(result.Positions, offset+at)
			at++
			if at < len(raw) && raw[at] == '\n' {
				at++
			}
			continue
		}
		result.Text += raw[at : at+1]
		result.Positions = append(result.Positions, offset+at)
		at++
	}
	return result
}

func agreementCommentCodeHTMLCitation(attributes []html.Attribute) bool {
	for _, attribute := range attributes {
		if attribute.Key != "class" {
			continue
		}
		for class := range strings.FieldsSeq(attribute.Val) {
			if class == "wikilink" || strings.HasPrefix(class, "wikilink-") {
				return true
			}
		}
	}
	return false
}

func agreementCommentCodeHTMLWindows(raw string) ([]agreementCommentCodeHTMLWindow, bool) {
	parts, valid := agreementCodeWindowParts(raw)
	if !valid {
		return nil, false
	}
	for _, window := range parts {
		for _, part := range window {
			if part.Field {
				return nil, false
			}
		}
	}
	var windows []agreementCommentCodeHTMLWindow
	tokens := html.NewTokenizer(strings.NewReader(raw))
	active, offset := false, 0
	for {
		kind := tokens.Next()
		bytes := string(tokens.Raw())
		start := offset
		offset += len(bytes)
		if kind == html.ErrorToken {
			if !errors.Is(tokens.Err(), io.EOF) || active || len(windows) != len(parts) {
				return nil, false
			}
			for i, window := range windows {
				var text strings.Builder
				for _, part := range parts[i] {
					text.WriteString(part.Text)
				}
				if window.Text != text.String() || len(window.Text) != len(window.Positions) {
					return nil, false
				}
			}
			return windows, true
		}
		token := tokens.Token()
		startTag := kind == html.StartTagToken || kind == html.SelfClosingTagToken
		if startTag && token.Data == "code" {
			if active || kind == html.SelfClosingTagToken {
				return nil, false
			}
			active = true
			windows = append(windows, agreementCommentCodeHTMLWindow{})
		}
		if startTag && active && agreementCommentCodeHTMLCitation(token.Attr) {
			return nil, false
		}
		if kind == html.EndTagToken && token.Data == "code" {
			if !active {
				return nil, false
			}
			active = false
		}
		if kind == html.TextToken && active {
			text := agreementCommentCodeHTMLText(bytes, start)
			if text.Text != token.Data {
				return nil, false
			}
			last := &windows[len(windows)-1]
			last.Text += text.Text
			last.Positions = append(last.Positions, text.Positions...)
		}
	}
}

func agreementCommentCodeHTMLSites(text, word string) []int {
	var sites []int
	for at := 0; at < len(text); {
		found := strings.Index(text[at:], word)
		if found < 0 {
			break
		}
		at += found
		sites = append(sites, at)
		at += len(word)
	}
	return sites
}

func agreementCommentCodeHTMLProjection(body, raw, private, projected string, positions []int, native []agreementNativeCodeWindow, fields []agreementCommentCodeHTMLField) bool {
	windows, valid := agreementCommentCodeHTMLWindows(raw)
	if !valid || len(fields) == 0 || len(windows) != len(native) || len(projected) != len(positions) {
		return false
	}
	old := fields[0].Target
	if old == "" {
		return false
	}
	word, replacement := "[["+old+"]]", strings.Repeat("q", len(old))
	hits, edits := make([]int, len(fields)), map[int]byte{}
	for wi, window := range windows {
		span := native[wi].Span
		if span.Start < 0 || span.Stop > len(positions) || span.Start > span.Stop {
			return false
		}
		var owned []int
		for fi, field := range fields {
			if field.Target != old {
				return false
			}
			if span.Start <= field.ProjectedSpan.Start && field.ProjectedSpan.Stop <= span.Stop {
				owned = append(owned, fi)
			}
		}
		if len(owned) == 0 {
			continue
		}
		if span.Start == span.Stop {
			return false
		}
		left, right := positions[span.Start], positions[span.Stop-1]+1
		if left < 0 || right > len(body) || left > right {
			return false
		}
		sourceSites, textSites := agreementCommentCodeHTMLSites(body[left:right], word), agreementCommentCodeHTMLSites(window.Text, word)
		if len(sourceSites) != len(textSites) {
			return false
		}
		for _, fi := range owned {
			field := fields[fi]
			a, b := field.OriginalSpan.Start, field.OriginalSpan.Stop
			c, d := field.ProjectedSpan.Start, field.ProjectedSpan.Stop
			if a < 0 || b > len(body) || a >= b || c < 0 || d > len(projected) || c >= d || body[a:b] != word || projected[c:d] != word || b-a != d-c {
				return false
			}
			for at := a; at < b; at++ {
				if positions[c+at-a] != at {
					return false
				}
			}
			ordinal := slices.Index(sourceSites, a-left)
			if ordinal < 0 {
				return false
			}
			at := textSites[ordinal] + 2
			if at+len(old) > len(window.Positions) {
				return false
			}
			for i := range len(old) {
				pos := window.Positions[at+i]
				if _, used := edits[pos]; used || pos < 0 || pos >= len(raw) || raw[pos] != old[i] {
					return false
				}
				edits[pos] = replacement[i]
			}
			hits[fi]++
		}
	}
	for _, count := range hits {
		if count != 1 {
			return false
		}
	}
	expected := []byte(raw)
	for pos, value := range edits {
		expected[pos] = value
	}
	return string(expected) == private
}

